const input = $input.first().json;
const reply = (input.output || input.reply || '').trim();

const output = {
  conversationId: input.conversationId,
  reply: reply,
  callbackUrl: input.callbackUrl
};

// Detect if the AI is asking the "new vs continue" question
const isSelectionQuestion = /\b(новый пресейл|нового пресейла|существующий|continue existing|start a new|new presale|create a new|existing one|существующего)\b/i.test(reply) &&
  /\b(выбрать|choose|хотите|want|would you|хотите|начать|start)\b/i.test(reply);

if (isSelectionQuestion) {
  output.attachments = [{
    contentType: "application/vnd.microsoft.card.adaptive",
    content: {
      type: "AdaptiveCard",
      version: "1.5",
      body: [
        {
          type: "TextBlock",
          size: "Medium",
          weight: "Bolder",
          text: "🤖 Presale Processing Agent"
        },
        {
          type: "TextBlock",
          text: reply,
          wrap: true
        }
      ],
      actions: [
        {
          type: "Action.Submit",
          title: "🆕 Start a new presale",
          data: { intent: "new_presale" }
        },
        {
          type: "Action.Submit",
          title: "📋 Continue an existing presale",
          data: { intent: "continue_presale" }
        }
      ]
    }
  }];
}

return [{ json: output }];
